-- Desired database schema for the control plane (source of truth, decision D19).
-- Edit this file, then run `mise run db:diff <name>` to generate a goose migration.
-- Entities are specified in docs/spec/02-domain-model.md. Columns arrive with the
-- milestone that needs them; M1 covers Project, Issue, Run, StepRun and Event.
-- IDs are UUIDv7 generated by the application.

CREATE TABLE projects (
  id                uuid        PRIMARY KEY,
  name              text        NOT NULL UNIQUE,
  -- Issue key prefix (D22): immutable, branch-safe.
  key_prefix        text        NOT NULL UNIQUE CHECK (key_prefix ~ '^[a-z][a-z0-9]{1,9}$'),
  next_issue_number integer     NOT NULL DEFAULT 1 CHECK (next_issue_number >= 1),
  -- specApproval from the repo's .factory/config.yaml, synced by intake (D64).
  spec_approval     boolean     NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE issues (
  id                  uuid        PRIMARY KEY,
  project_id          uuid        NOT NULL REFERENCES projects (id),
  -- Allocated from projects.next_issue_number; key is <key_prefix>-<number> (D22).
  number              integer     NOT NULL CHECK (number >= 1),
  key                 text        NOT NULL UNIQUE,
  -- epic > story > task/bug (D57); the store checks the types and that the parent is in the same project.
  parent_id           uuid        REFERENCES issues (id),
  type                text        NOT NULL CHECK (type IN ('epic', 'story', 'task', 'bug')),
  title               text        NOT NULL,
  spec                text        NOT NULL DEFAULT '',
  acceptance_criteria text[]      NOT NULL DEFAULT '{}',
  status              text        NOT NULL DEFAULT 'draft' CHECK (status IN (
                        'draft', 'refining', 'ready', 'running', 'awaiting_human',
                        'queued', 'merged', 'released', 'failed', 'canceled')),
  priority            integer     NOT NULL DEFAULT 0,
  source_ref          text,
  labels              text[]      NOT NULL DEFAULT '{}',
  created_by          text        NOT NULL,
  -- Someone asked to start this issue, or everything under it (D62).
  start_requested_at  timestamptz,
  start_requested_by  text,
  -- When the scheduler last started it; holds a slot until its run exists (D62).
  scheduled_at        timestamptz,
  -- Paths the issue is expected to touch, from its text or refinement, and the
  -- files its latest change touched; compared for overlap warnings (D63).
  file_hints          text[]      NOT NULL DEFAULT '{}',
  changed_paths       text[]      NOT NULL DEFAULT '{}',
  -- Spec approval (D64): who approved the spec, or why it was last rejected. A
  -- rejected draft is held until its text changes or someone asks to start it again.
  spec_approved_at    timestamptz,
  spec_approved_by    text,
  spec_rejected_at    timestamptz,
  spec_feedback       text        NOT NULL DEFAULT '',
  -- The refiner's result (a domain.RefinedSpec) while it waits for approval (D66).
  spec_proposal       jsonb,
  -- Closing by a person (D70): completing a parent (-> merged) or canceling,
  -- who did it, when, and the reason a cancel gave.
  closed_at           timestamptz,
  closed_by           text,
  close_reason        text        NOT NULL DEFAULT '',
  -- When the provider issue was closed to match (D71); null while that is
  -- still to do for an issue a person closed.
  source_closed_at    timestamptz,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  -- An external issue (e.g. a GitHub issue URL) syncs into at most one Issue per project.
  CONSTRAINT issues_project_source_ref_key UNIQUE (project_id, source_ref),
  CONSTRAINT issues_project_number_key UNIQUE (project_id, number)
);

CREATE INDEX issues_parent_id_idx ON issues (parent_id);

-- The dependency DAG (D57): issue_id waits for depends_on_id. Both are in the same
-- project, and the store rejects edges that close a cycle (counting the hierarchy).
CREATE TABLE issue_dependencies (
  issue_id      uuid        NOT NULL REFERENCES issues (id),
  depends_on_id uuid        NOT NULL REFERENCES issues (id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (issue_id, depends_on_id),
  CONSTRAINT issue_dependencies_not_self CHECK (issue_id <> depends_on_id)
);

CREATE INDEX issue_dependencies_depends_on_id_idx ON issue_dependencies (depends_on_id);

CREATE INDEX issues_project_status_idx ON issues (project_id, status);

-- A Run belongs to an issue, or to a release whose agent it runs (D129);
-- exactly one of issue_id and release_id is set (release_id's foreign key is
-- added after releases).
CREATE TABLE runs (
  id                   uuid        PRIMARY KEY,
  issue_id             uuid        REFERENCES issues (id),
  release_id           uuid,
  workflow_snapshot    jsonb       NOT NULL,
  workflow_version     text        NOT NULL,
  -- Stable per issue (e.g. issue-gc-1) and reused by reruns; the Temporal run ID
  -- identifies one execution, so it is what makes a Run unique.
  temporal_workflow_id text        NOT NULL,
  temporal_run_id      text        UNIQUE,
  status               text        NOT NULL DEFAULT 'pending' CHECK (status IN (
                         'pending', 'running', 'succeeded', 'failed', 'canceled')),
  loop_counts          jsonb       NOT NULL DEFAULT '{}',
  started_at           timestamptz,
  finished_at          timestamptz,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT runs_issue_or_release_check CHECK ((issue_id IS NULL) <> (release_id IS NULL))
);

-- At most one active Run per Issue; a retry creates a new Run after the old one ends.
CREATE UNIQUE INDEX runs_one_active_per_issue_idx ON runs (issue_id) WHERE status IN ('pending', 'running');

CREATE TABLE step_runs (
  id          uuid        PRIMARY KEY,
  run_id      uuid        NOT NULL REFERENCES runs (id),
  step_id     text        NOT NULL,
  attempt     integer     NOT NULL CHECK (attempt >= 1),
  kind        text        NOT NULL CHECK (kind IN ('agent', 'gate', 'action', 'parallel')),
  status      text        NOT NULL DEFAULT 'pending' CHECK (status IN (
                'pending', 'running', 'succeeded', 'failed', 'canceled')),
  pod_name    text,
  commit_sha  text,
  -- An agent session's model usage (D53): cost as the LLM gateway recorded
  -- it for the session's key, tokens as the harness reported them.
  cost_usd      double precision NOT NULL DEFAULT 0 CHECK (cost_usd >= 0),
  input_tokens  bigint           NOT NULL DEFAULT 0 CHECK (input_tokens >= 0),
  output_tokens bigint           NOT NULL DEFAULT 0 CHECK (output_tokens >= 0),
  started_at  timestamptz,
  finished_at timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT step_runs_run_step_attempt_key UNIQUE (run_id, step_id, attempt)
);

-- Append-only. seq gives a strict total order for streaming and replay (FR-OB-2).
CREATE TABLE events (
  id          uuid        PRIMARY KEY,
  seq         bigint      NOT NULL GENERATED ALWAYS AS IDENTITY UNIQUE,
  run_id      uuid        REFERENCES runs (id),
  step_run_id uuid        REFERENCES step_runs (id),
  session_id  uuid,
  ts          timestamptz NOT NULL,
  type        text        NOT NULL,
  payload     jsonb       NOT NULL DEFAULT '{}',
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX events_run_seq_idx ON events (run_id, seq);

-- A change request (PR/MR) opened for an issue's branch; neutral across providers (D12).
CREATE TABLE change_requests (
  id           uuid        PRIMARY KEY,
  issue_id     uuid        NOT NULL REFERENCES issues (id),
  run_id       uuid        NOT NULL REFERENCES runs (id),
  repo         text        NOT NULL,
  number       integer     NOT NULL,
  provider_ref text        NOT NULL,
  branch       text        NOT NULL,
  head_sha     text        NOT NULL,
  status       text        NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'merged', 'closed')),
  -- The commit the merge made on the base branch, when the merge queue made it
  -- (a merge made by a person on the provider records none), and when the
  -- control plane recorded the merge: the order releases include issues in (D110).
  merge_sha    text,
  merged_at    timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT change_requests_repo_number_key UNIQUE (repo, number)
);

-- The outcome of one gate StepRun (docs/spec/02, GateResult). The commit it
-- judged is the StepRun's commit_sha. One result per gate StepRun; a loop back
-- (M3) creates a new StepRun attempt.
CREATE TABLE gate_results (
  id          uuid        PRIMARY KEY,
  step_run_id uuid        NOT NULL REFERENCES step_runs (id),
  gate_type   text        NOT NULL CHECK (gate_type IN ('command', 'agent-verdict', 'human', 'provider-checks', 'preserve', 'preview')),
  policy      text        NOT NULL CHECK (policy IN ('blocking', 'advisory')),
  verdict     text        NOT NULL CHECK (verdict IN ('pass', 'fail', 'escalated')),
  details     jsonb       NOT NULL DEFAULT '{}',
  created_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT gate_results_step_run_key UNIQUE (step_run_id)
);

-- A decision a human gate waits for (docs/spec/03: human gates are Signals).
-- The workflow writes it when the gate opens and when it closes; the API only
-- reads it and signals the workflow, so the workflow stays the single writer.
CREATE TABLE approvals (
  id                 uuid        PRIMARY KEY,
  step_run_id        uuid        NOT NULL REFERENCES step_runs (id),
  run_id             uuid        NOT NULL REFERENCES runs (id),
  reason             text        NOT NULL,
  commit_sha         text,
  change_request_url text,
  status             text        NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'timed_out', 'changes_requested')),
  -- Whether a person may send the change back to the coder instead of
  -- approving or rejecting it (D92): the gates before a merge.
  can_request_changes boolean  NOT NULL DEFAULT false,
  decided_by         text,
  comment            text,
  expires_at         timestamptz NOT NULL,
  decided_at         timestamptz,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT approvals_step_run_key UNIQUE (step_run_id)
);

CREATE INDEX approvals_status_idx ON approvals (status, created_at);

-- Questions an agent asked a person with the ask-human tool (D55): the
-- session's activity writes one when it sees the question event, the
-- InterveneSession activity records its answer, and finishing the step run
-- expires the ones nobody answered. question_id is the runner's.
CREATE TABLE questions (
  id          uuid        PRIMARY KEY,
  step_run_id uuid        NOT NULL REFERENCES step_runs (id),
  run_id      uuid        NOT NULL REFERENCES runs (id),
  question_id text        NOT NULL,
  question    text        NOT NULL,
  status      text        NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'answered', 'expired')),
  answer      text,
  answered_by text,
  answered_at timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT questions_step_run_question_key UNIQUE (step_run_id, question_id)
);

CREATE INDEX questions_status_idx ON questions (status, created_at);

-- The digest each toolchain image was built as (open question 15, D45). Pods
-- run toolchain images by this digest only: the registry is writable by build
-- pods, so a tag there proves nothing.
CREATE TABLE toolchain_images (
  repository text        NOT NULL,
  tag        text        NOT NULL,
  digest     text        NOT NULL CHECK (digest ~ '^sha256:[0-9a-f]{64}$'),
  built_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (repository, tag)
);

-- A Release (D110): a commit of a project's repository plus the issues it
-- contains, moving through the project's stages (configuration, not rows).
CREATE TABLE releases (
  id          uuid        PRIMARY KEY,
  project_id  uuid        NOT NULL REFERENCES projects (id),
  repo        text        NOT NULL,
  sha         text        NOT NULL,
  status      text        NOT NULL DEFAULT 'pending' CHECK (status IN (
                'pending', 'in_progress', 'succeeded', 'failed', 'rolled_back')),
  -- Why it failed or was rolled back (D114).
  reason      text        NOT NULL DEFAULT '',
  -- The bug issue opened on the provider when its verification failed (D115).
  bug_issue_ref text,
  -- What the release agent prepared (D129): the proposed bump, the notes and
  -- whether the agent wrote them or the fallback did.
  bump         text        NOT NULL DEFAULT '' CHECK (bump IN ('', 'major', 'minor', 'patch')),
  notes        text        NOT NULL DEFAULT '',
  notes_source text        NOT NULL DEFAULT '' CHECK (notes_source IN ('', 'agent', 'fallback')),
  -- The version a succeeded release got, its provider release, and why
  -- publishing it failed, if it did (D129).
  version              text NOT NULL DEFAULT '',
  provider_release_url text NOT NULL DEFAULT '',
  publish_error        text NOT NULL DEFAULT '',
  finished_at timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  -- Creating the release of a commit again returns the first one.
  CONSTRAINT releases_project_repo_sha_key UNIQUE (project_id, repo, sha)
);

CREATE INDEX releases_project_created_idx ON releases (project_id, created_at);

-- The issues a release contains. An issue is in every release made while it
-- is merged and not yet released, so a failed release's issues are in the next.
CREATE TABLE release_issues (
  release_id uuid        NOT NULL REFERENCES releases (id),
  issue_id   uuid        NOT NULL REFERENCES issues (id),
  position   integer     NOT NULL CHECK (position >= 1),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (release_id, issue_id)
);

CREATE INDEX release_issues_issue_id_idx ON release_issues (issue_id);

-- A release at one stage: what its driver did (driver_state, opaque to the
-- control plane, D109) and how it ended.
CREATE TABLE deployments (
  id           uuid        PRIMARY KEY,
  release_id   uuid        NOT NULL REFERENCES releases (id),
  stage        text        NOT NULL,
  driver       text        NOT NULL,
  driver_state jsonb       NOT NULL DEFAULT '{}',
  status       text        NOT NULL DEFAULT 'pending' CHECK (status IN (
                 'pending', 'in_progress', 'succeeded', 'failed', 'rolled_back')),
  reason       text        NOT NULL DEFAULT '',
  -- How the stage's verification ended, once it ran (D130).
  verification jsonb,
  started_at   timestamptz,
  finished_at  timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT deployments_release_stage_key UNIQUE (release_id, stage)
);

ALTER TABLE runs ADD CONSTRAINT runs_release_id_fkey FOREIGN KEY (release_id) REFERENCES releases (id);

CREATE INDEX runs_release_id_idx ON runs (release_id);

-- People who sign in to Frankie (D144, M10).
CREATE TABLE users (
  id            uuid        PRIMARY KEY,
  username      text        NOT NULL UNIQUE CHECK (username ~ '^[a-z0-9][a-z0-9._-]{0,63}$'),
  display_name  text        NOT NULL DEFAULT '',
  email         text,
  role          text        NOT NULL CHECK (role IN ('admin', 'member', 'viewer')),
  password_hash text        NOT NULL DEFAULT '',
  disabled_at   timestamptz,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX users_email_lower_idx ON users (lower(email)) WHERE email IS NOT NULL AND email <> '';

-- External SSO identities linked to a user (D144, D145); one person can link several.
CREATE TABLE user_identities (
  id         uuid        PRIMARY KEY,
  user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  provider   text        NOT NULL CHECK (provider IN ('google', 'gitlab', 'github')),
  subject    text        NOT NULL,
  email      text        NOT NULL DEFAULT '',
  login      text        NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT user_identities_provider_subject_key UNIQUE (provider, subject)
);

CREATE INDEX user_identities_user_id_idx ON user_identities (user_id);

-- Browser sessions carried in an HttpOnly cookie (D144); only SHA-256 hashes are stored.
CREATE TABLE sessions (
  id           uuid        PRIMARY KEY,
  user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  token_hash   bytea       NOT NULL UNIQUE,
  expires_at   timestamptz NOT NULL,
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX sessions_user_id_idx ON sessions (user_id);
CREATE INDEX sessions_expires_at_idx ON sessions (expires_at);

-- Per-person API tokens replacing the single token (D144, D146); only SHA-256 hashes are stored.
CREATE TABLE api_tokens (
  id           uuid        PRIMARY KEY,
  user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  name         text        NOT NULL,
  token_prefix text        NOT NULL,
  token_hash   bytea       NOT NULL UNIQUE,
  last_used_at timestamptz,
  expires_at   timestamptz,
  revoked_at   timestamptz,
  created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX api_tokens_user_id_idx ON api_tokens (user_id);

-- Administrator invitations to join Frankie (D145); single-use and expiring.
CREATE TABLE user_invites (
  id          uuid        PRIMARY KEY,
  token_hash  bytea       NOT NULL UNIQUE,
  email       text        NOT NULL DEFAULT '',
  role        text        NOT NULL CHECK (role IN ('admin', 'member', 'viewer')),
  invited_by  uuid        REFERENCES users (id) ON DELETE SET NULL,
  expires_at  timestamptz NOT NULL,
  accepted_at timestamptz,
  accepted_by uuid        REFERENCES users (id) ON DELETE SET NULL,
  created_at  timestamptz NOT NULL DEFAULT now()
);
